  color: #0a2324;
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: 2.15rem;
  line-height: 0.82;
  letter-spacing: 0;
  text-decoration: none !important;
}

.newsletter-consent-brand-city {
  font-weight: 500;
}

.newsletter-consent-brand-live {
  font-weight: 300;
}

.newsletter-consent-main {
  width: min(100% - 2rem, 44rem);
  margin: 2rem auto 4rem;
}

