}

.newsletter-consent-form,
.newsletter-consent-email {
  display: grid;
  gap: 0.65rem;
  min-width: 0;
}

.newsletter-consent-form {
  gap: 1.5rem;
}

.newsletter-consent-email input {
  width: 100%;
  min-width: 0;
  min-height: 3rem;
  padding: 0.65rem;
