  border-radius: 4px;
  background: #fff;
  font: inherit;
}

.newsletter-consent-options {
  display: grid;
  gap: 1.5rem;
  grid-column: 1 / -1;
}

.newsletter-consent-option {
  display: grid;
  grid-template-columns: 1.5rem minmax(0, 1fr);
  gap: 0.75rem;
  align-items: start;
  padding-top: 1rem;
  border-top: 1px solid #dbe2e1;
  font-size: 1rem;
  line-height: 1.5;
}

.newsletter-consent-option input[type="checkbox"] {
