  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.25rem;
  accent-color: #096b65;
}

.newsletter-consent-option label {
  display: block;
  font-weight: 700;
  cursor: pointer;
}

.newsletter-consent-option p {
  margin-top: 0.5rem;
}

.newsletter-consent-optional {
  display: block;
  color: #47615c;
  font-size: 0.875rem;
  margin-bottom: 0.25rem;
}

.newsletter-consent-form input[type="submit"] {
