  max-width: 100%;
  min-height: 2.75rem;
  padding: 0.65rem 1.25rem;
  border: 0;
  border-radius: 4px;
  background: #0a2324;
  color: #fff;
.skip-link {
position: absolute;
  left: 1rem;
  top: 0.75rem;
  z-index: 120;
  padding: 0.65rem 0.9rem;
  background: var(--ink);
  color: #fff;
  font-weight: 700;
  text-decoration: none;
  transform: translateY(-140%);
  transition: transform 140ms ease;
