  --line: #c6c6c6;
}

body {
margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: "Archivo Narrow", "Arial Narrow", sans-serif;
}

html {
scroll-behavior: smooth;
}

.sr-only {
position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
position: absolute;
  left: 1rem;
  top: 0.75rem;
  z-index: 120;
  padding: 0.65rem 0.9rem;
  background: var(--ink);
  color: #fff;
  font-weight: 700;
  text-decoration: none;
  transform: translateY(-140%);
  transition: transform 140ms ease;
}

.skip-link:focus-visible {
transform: translateY(0);
}

input,
textarea,
select,
button {
font: inherit;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:not([tabindex="-1"]):focus-visible {
outline: 3px solid var(--accent);
  outline-offset: 3px;
}

a {
color: inherit;
}

.app-nav {
position: sticky;
  top: 0;
  z-index: 30;
  border-bottom: 1px solid var(--line);
  background:
    linear-gradient(120deg, rgba(231, 92, 88, 0.34) 0%, rgba(240, 154, 70, 0.3) 24%, rgba(244, 216, 96, 0.28) 46%, rgba(129, 183, 231, 0.24) 72%, rgba(156, 208, 165, 0.28) 100%);
  backdrop-filter: blur(8px);
}

.app-nav-inner {
max-width: 1220px;
  margin: 0 auto;
  padding: 0.85rem 1rem;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  position: relative;
}

