const auditCode = `async (page) => {
 const routes = __ROUTES__;
 const size = __SIZE__;
 await page.setViewportSize(size);
 const results = [];
 for (const route of routes) {
  const errors = [];
  const onError = msg => { if (msg.type() === 'error') errors.push(msg.text().slice(0,400)); };
  page.on('console',onError);
  const started = Date.now();
  try {
   const response = await page.goto('http://127.0.0.1:3000'+route,{waitUntil:'domcontentloaded',timeout:20000});
   await page.evaluate(() => document.fonts.ready);
   await page.addScriptTag({path:'/Users/marc/Projects/stuttgart-live.de/output/playwright/frontend-audit/axe.min.js'});
   const data = await page.evaluate(async () => {
    const visible = e => { const r=e.getBoundingClientRect(); return e.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}) && r.width>0 && r.height>0; };
    const controls = [...document.querySelectorAll('a,button,input:not([type="hidden"]),select,summary')].filter(visible);
    const targets = controls.filter(e=>{const r=e.getBoundingClientRect();return r.width<44||r.height<44}).map(e=>({tag:e.tagName,name:(e.getAttribute('aria-label')||e.innerText||e.getAttribute('placeholder')||'').trim().slice(0,65),class:e.className,width:+e.getBoundingClientRect().width.toFixed(1),height:+e.getBoundingClientRect().height.toFixed(1)}));
    const axeResult = await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa','best-practice']}});
    return {
     title:document.title,h1:[...document.querySelectorAll('h1')].map(e=>e.innerText),mainCount:document.querySelectorAll('main').length,
     viewport:innerWidth,scrollWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,
     brokenImages:[...document.images].filter(e=>e.complete&&!e.naturalWidth).map(e=>e.currentSrc).slice(0,5),
     controlCount:controls.length,smallTargets:targets.slice(0,12),smallTargetCount:targets.length,
     violations:axeResult.violations.map(v=>({id:v.id,impact:v.impact,help:v.help,total:v.nodes.length,nodes:v.nodes.slice(0,4).map(n=>({target:n.target,html:n.html,summary:n.failureSummary}))})),
     incomplete:axeResult.incomplete.map(v=>({id:v.id,count:v.nodes.length})),passCount:axeResult.passes.length,
     resources:performance.getEntriesByType('resource').reduce((o,e)=>{o.count++;o.bytes+=e.transferSize||0;o.duration=Math.max(o.duration,e.responseEnd);return o},{count:0,bytes:0,duration:0})
    };
   });
   results.push({route,status:response.status(),finalUrl:page.url(),elapsedMs:Date.now()-started,...data,errors});
  } catch(error) { results.push({route,error:String(error),errors}); }
  page.off('console',onError);
 }
 return results;
}`;
store("auditCode",auditCode);
