    event_month: selected_month_param,
    event_date: selected_date&.iso8601,
    event_genre: selected_genre&.slug,
    event_location: selected_location
  }.compact
  base_genre_params = base_filter_params.except(:event_genre)
  base_location_params = base_filter_params.except(:event_location)
  active_filter_chips = []
  if selected_date.present?
    active_filter_chips << {
      label: display_title,
      path: all_stuttgart_lane_path(base_filter_params.except(:event_date))
    }
  end
  if selected_genre.present?
    active_filter_chips << {
      label: selected_genre.name,
      path: all_stuttgart_lane_path(base_genre_params)
    }
  end
  if selected_location.present?
    active_filter_chips << {
      label: selected_location,
      path: all_stuttgart_lane_path(base_location_params)
    }
  end
