.design-preview-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.design-preview-section h2 {
  scroll-margin-top: 7rem;
  font-size: clamp(1.15rem, 1.6vw, 1.5rem);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: 0;
  text-transform: uppercase;
}

.design-preview-heading-mobile {
  display: none;
}

.design-preview-highlight-grid,
.design-preview-format-grid,
.design-preview-card-row,
.design-preview-wide-grid,
.design-preview-genre-grid {
  display: grid;
  gap: 0.75rem;
}

.design-preview-highlight-grid,
.design-preview-card-row,
.design-preview-wide-grid {
  grid-template-columns: minmax(0, 1fr);
}

.design-preview-format-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-radius: 0.5rem;
}

.design-preview-list-page .genre-lane-card-copy .event-listing-body {
  align-content: start;
}

.design-preview-list-section {
  margin-top: clamp(1.1rem, 2.4vw, 2rem);
}

.search-results-section {
  margin-top: clamp(0.35rem, 1.2vw, 0.9rem);
}

.search-results-header {
  margin-bottom: clamp(1rem, 2vw, 1.45rem);
}

.search-results-title {
  margin: 0;
  color: var(--preview-ink);
  font-family: "Oswald", "Arial Narrow", sans-serif;
  font-size: clamp(2.05rem, 6.4vw, 3.35rem);
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0;
  text-transform: uppercase;
}

.design-preview-list-section .design-preview-section-header {
  margin-bottom: 0.75rem;
}

.design-preview-list-page .lane-page-pagination {
  max-width: none;
  margin-top: 2rem;
  padding: 0;
  border: 0;
  background: transparent;
}

<% container_id = local_assigns[:container_id] %>
<% wrap = local_assigns.fetch(:wrap, true) %>
<% effective_series_ids = local_assigns[:effective_series_ids] || effective_public_event_series_ids(events) %>
<% series_counts_by_id = local_assigns[:series_counts_by_id] || {} %>
<% row_dom_id_prefix = local_assigns[:row_dom_id_prefix] %>
<% strict_proxy = local_assigns.fetch(:strict_proxy, false) %>

<% if wrap && container_id.present? %>
  <div class="event-listing-grid" id="<%= container_id %>">
<% elsif wrap %>
  <div class="event-listing-grid">
<% end %>
  <% events.each do |event| %>
    <%= render "event_list_row",
               event: event,
               browse_state: browse_state,
               effective_series_ids: effective_series_ids,
               series_counts_by_id: series_counts_by_id,
               strict_proxy: strict_proxy,
               row_dom_id: (row_dom_id_prefix.present? ? dom_id(event, row_dom_id_prefix) : nil) %>
  <% end %>
<% if wrap %>
  </div>
<% end %>
<% presenter = public_news_show_presenter(@blog_post) %>
<%= render "show_meta", presenter: presenter %>
<% if authenticated? && current_user.blog_access? %>
  <% content_for :public_backend_actions do %>
    <%= link_to "Edit",
                edit_backend_blog_post_path(@blog_post),
                class: "button button-secondary button-compact event-detail-edit-link public-edit-link public-backend-shortcut",
                data: { turbo: false } %>
  <% end %>
<% end %>
<% content_for :page_newsletter do %><% end %>
<% content_for :page_partner_strip do %><% end %>
<% strict_proxy = homepage_media_strict_proxy? %>
<% genre_lanes = public_design_navigation_lanes(Array(@news_preview_genre_lanes).first(5), highlight_events: @news_preview_highlight_events) %>
<% sidebar_events = Array(@news_preview_sidebar_events) %>
<% design_chrome_saved_events = (sidebar_events + Array(@news_preview_highlight_events) + genre_lanes.flat_map { |lane| Array(lane.events) }).compact.uniq(&:id) %>

<div class="design-preview design-news-preview-shell"
     data-controller="design-preview-menu design-preview-filterbar">
  <%= render "public/events/design_preview_header",
             browse_state: @browse_state,
             genre_lanes: genre_lanes,
             search_overlay: @design_preview_search_overlay,
             menu_groups: public_design_menu_groups,
             saved_events: design_chrome_saved_events,
             strict_proxy: strict_proxy %>

  <article class="event-detail news-detail design-news-preview-detail">
    <div class="event-detail-topbar">
      <p class="event-detail-back">
        <%= link_to presenter.back_path,
                    class: "design-detail-preview-back",
                    aria: { label: "Zurück" },
                    data: { controller: "history-back-link", action: "click->history-back-link#navigate" } do %>
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <path d="M19 12H6"></path>
            <path d="m11 6-6 6 6 6"></path>
          </svg>
          Zurück
        <% end %>
      </p>
    </div>

    <section class="design-service-preview-layout design-news-preview-layout design-news-preview-layout--article" aria-label="News Inhalt">
      <div class="design-service-preview-content design-news-preview-article">
        <%= render "show_header_copy", presenter: presenter %>

        <section class="event-detail-panel event-detail-copy event-detail-copy-primary news-detail-copy news-detail-body-copy">
          <%= presenter.body %>
        </section>

        <div class="design-news-preview-share">
          <%= render "public/events/share_event_button",
                     presenter: presenter,
                     share_headline: presenter.headline,
                     share_text: presenter.teaser,
                     share_label: "#{presenter.headline} teilen",
                     button_class: "design-detail-preview-action-button",
                     show_text: true %>
        </div>

        <% if presenter.has_video_block? %>
          <div class="design-news-preview-media">
            <%= render "show_media", presenter: presenter %>
          </div>
        <% elsif presenter.hero_image? %>
          <div class="design-news-preview-media design-news-preview-media--image">
            <%= render "show_image", presenter: presenter %>
          </div>
        <% end %>
      </div>

      <% if sidebar_events.any? %>
        <%= render "public/events/design_preview_detail_related",
                   title: @news_preview_sidebar_title,
                   title_id: "design-news-preview-related-title",
                   wrapper_class: "design-preview-section design-detail-preview-related design-news-preview-highlights",
                   related_preview_events: sidebar_events,
                   related_effective_series_ids: @news_preview_effective_series_ids,
                   series_counts_by_id: @news_preview_series_counts_by_id,
                   browse_state: @browse_state,
                   strict_proxy: strict_proxy %>
      <% end %>
    </section>
  </article>

  <%= render "public/events/design_preview_footer", menu_groups: public_design_menu_groups %>
</div>

