  const test = async (name, fn) => { try { await fn(); results.push({name,status:'PASS'}) } catch (error) { results.push({name,status:'FAIL',message:error.message}) } }
  const home = async () => { await page.goto('http://127.0.0.1:3000'); await page.waitForFunction(()=>window.Stimulus && document.querySelector('[data-controller="design-preview-feature-slider"]') && window.Stimulus.getControllerForElementAndIdentifier(document.querySelector('[data-controller="design-preview-feature-slider"]'),'design-preview-feature-slider')) }
  const slider = fn => page.evaluate(fn)
  try {
    await home()
    await test('S shortcut focuses the visible search field', async () => {
      await page.keyboard.press('s')
      assert.equal(await page.evaluate(()=>document.activeElement.matches('[data-public-search-target="input"]') && document.activeElement.getClientRects().length > 0),true)
    })
    await home()
    await test('Reduced motion blocks every slider restart', async () => {
      await page.emulateMedia({reducedMotion:'reduce'})
      assert.equal(await slider(()=>{const e=document.querySelector('[data-controller="design-preview-feature-slider"]');const c=Stimulus.getControllerForElementAndIdentifier(e,'design-preview-feature-slider');c.next();return !!c.timer}),false)
    })
    await page.emulateMedia({reducedMotion:'no-preference'})
    await home()
    await test('Changing motion preference stops slider animation and autoplay immediately', async () => {
      await slider(()=>{const e=document.querySelector('[data-controller="design-preview-feature-slider"]');Stimulus.getControllerForElementAndIdentifier(e,'design-preview-feature-slider').next()})
      await page.emulateMedia({reducedMotion:'reduce'})
      await page.waitForTimeout(80)
      assert.deepEqual(await slider(()=>{const e=document.querySelector('[data-controller="design-preview-feature-slider"]');const c=Stimulus.getControllerForElementAndIdentifier(e,'design-preview-feature-slider');return [!!c.timer,c.trackTarget.style.transition]}),[false,'none'])
    })
    await page.emulateMedia({reducedMotion:'no-preference'})
    await home()
    await test('Explicit slider pause survives mouseleave, focusout and next', async () => {
      assert.equal(await slider(()=>{const e=document.querySelector('[data-controller="design-preview-feature-slider"]');const c=Stimulus.getControllerForElementAndIdentifier(e,'design-preview-feature-slider'); if(!c.toggleAutoplay)return 'missing pause control'; c.toggleAutoplay({preventDefault(){}});e.dispatchEvent(new MouseEvent('mouseleave'));e.dispatchEvent(new FocusEvent('focusout'));c.next();return !!c.timer}),false)
    })
    await home()
    await test('Pointer cancellation restores slider without moving a slide', async () => {
      assert.equal(await slider(()=>{const e=document.querySelector('[data-controller="design-preview-feature-slider"]');const c=Stimulus.getControllerForElementAndIdentifier(e,'design-preview-feature-slider');c.trackTarget.dispatchEvent(new PointerEvent('pointerdown',{pointerType:'touch',pointerId:1,clientX:300,clientY:100,button:0}));c.trackTarget.dispatchEvent(new PointerEvent('pointermove',{pointerType:'touch',pointerId:1,clientX:100,clientY:100}));c.trackTarget.dispatchEvent(new PointerEvent('pointercancel',{pointerType:'touch',pointerId:1,clientX:100,clientY:100}));return c.index}),0)
    })
    await page.emulateMedia({reducedMotion:'reduce'})
    await home()
    await test('Reduced motion leaves the video paused at its poster', async () => {
      await page.waitForTimeout(400)
      assert.equal(await page.locator('[data-video-sound-target="video"]').first().evaluate(v=>v.paused && v.currentTime === 0),true)
    })
    await test('Decorative video has explicit play/pause support', async () => {
      assert.equal(await page.evaluate(()=>{const e=document.querySelector('[data-controller="video-sound"]');return typeof Stimulus.getControllerForElementAndIdentifier(e,'video-sound').togglePlayback}), 'function')
    })
    await page.emulateMedia({reducedMotion:'no-preference'})
    await home()
    await test('Video responds to motion preference changes with a still poster', async () => {
      await page.waitForFunction(()=>{const v=document.querySelector('[data-video-sound-target="video"]');return !v.paused && v.currentTime > 0})
      await page.emulateMedia({reducedMotion:'reduce'})
      await page.waitForTimeout(120)
      assert.equal(await page.locator('[data-video-sound-target="video"]').first().evaluate(v=>v.paused && v.currentTime === 0),true)
    })

