const fs = require('node:fs')
const { chromium } = require('/Users/marc/.npm/_npx/31e32ef8478fbf80/node_modules/playwright')
const dir = __dirname
const old = JSON.parse(fs.readFileSync('/Users/marc/Projects/stuttgart-live.de/output/playwright/frontend-audit/evidence.json'))
;(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/Users/marc/Library/Caches/ms-playwright/chromium-1234/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing' })
  const page = await browser.newPage()
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  const results = []
  const cases = old.pages.map(x => ({route:x.route,width:x.viewport}))
  cases.push({route:'/alles-aus-stuttgart',width:768},{route:'/alles-aus-stuttgart',width:320},{route:'/',width:320})
  for (const [index, item] of cases.entries()) {
    await page.setViewportSize({width:item.width,height:1000})
    const start = errors.length
    const response = await page.goto(`http://127.0.0.1:3000${item.route}`, {waitUntil:'networkidle'})
    await page.addScriptTag({path:`${dir}/axe.min.js`})
    const data = await page.evaluate(async () => {
      const accessibility = await axe.run(document, {runOnly:{type:'tag', values:['wcag2a','wcag2aa','wcag21aa','best-practice']}})
      const visible = e => !!e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden'
      return {
        title:document.title, mainCount:document.querySelectorAll('main').length,
        h1:[...document.querySelectorAll('h1')].map(e=>e.textContent.trim()),
        scrollWidth:document.documentElement.scrollWidth,
        cardCount:document.querySelectorAll('.lane-page-grid .design-preview-card').length,
        controls:[...document.querySelectorAll('.saved-event-button.design-preview-card-save,.public-search-clear,.design-detail-preview-more-button')].filter(visible).map(e=>{const r=e.getBoundingClientRect();return {class:e.className,width:r.width,height:r.height}}),
        violations:accessibility.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))}))
      }
    })
    results.push({...item,status:response.status(),...data,errors:errors.slice(start)})
    if (item.route==='/' && item.width===1440) await page.screenshot({path:`${dir}/home-desktop.png`,fullPage:false})
    if (item.route==='/alles-aus-stuttgart' && item.width===768) await page.screenshot({path:`${dir}/all-stuttgart-tablet.png`,fullPage:false})
    if (item.route==='/events/mamma-mia-das-musical-2027-05-05' && item.width===390) await page.screenshot({path:`${dir}/event-mobile.png`,fullPage:false})
    console.log(JSON.stringify({index:index+1,route:item.route,width:item.width,status:response.status(),violations:data.violations.map(v=>[v.id,v.nodes.length]),overflow:data.scrollWidth>item.width,errors:errors.slice(start)}))
  }
  fs.writeFileSync(`${dir}/evidence.json`,JSON.stringify({date:new Date().toISOString(),results},null,2))
  await browser.close()
})().catch(e=>{console.error(e);process.exit(1)})

